package edu.facilities.ui; import edu.facilities.model.*; import edu.facilities.service.*; import javafx.fxml.*; import javafx.collections.*; import javafx.scene.control.*; import java.sql.*;
public class TicketsViewController { @FXML private TableView<MaintenanceTicket> ticketsTable; @FXML private TableColumn<MaintenanceTicket,String> idColumn,roomColumn,descriptionColumn,statusColumn,createdColumn; @FXML private Label messageLabel; @FXML public void initialize(){idColumn.setCellValueFactory(x->new javafx.beans.property.SimpleStringProperty(x.getValue().getId()));roomColumn.setCellValueFactory(x->new javafx.beans.property.SimpleStringProperty(x.getValue().getRoom().getName()));descriptionColumn.setCellValueFactory(x->new javafx.beans.property.SimpleStringProperty(x.getValue().getDescription()));statusColumn.setCellValueFactory(x->new javafx.beans.property.SimpleStringProperty(x.getValue().getStatus().name()));createdColumn.setCellValueFactory(x->new javafx.beans.property.SimpleStringProperty(x.getValue().getCreatedAt().toString()));try{ticketsTable.setItems(FXCollections.observableArrayList(new MaintenanceService().getTickets(AuthService.getInstance().getCurrentUser())));}catch(Exception e){messageLabel.setText(e.getMessage());}}}
